import Foundation

/// Where a piece of knowledge came from. The UI badges every item with it, and the AI
/// must keep these apart when answering (spec §4: verified vs notes vs manufacturer vs AI).
public enum Provenance: String, Codable, Sendable, CaseIterable {
    /// A procedure the owner has confirmed works on this house.
    case verifiedInstruction
    /// The owner's own notes, not formally verified.
    case userNote
    /// Manuals, datasheets and other manufacturer material.
    case manufacturerDocument
    /// Generated by the assistant. Always treated as unverified until the owner verifies it.
    case aiSuggestion

    public var displayName: String {
        switch self {
        case .verifiedInstruction: "Verified"
        case .userNote: "Your note"
        case .manufacturerDocument: "Manufacturer"
        case .aiSuggestion: "Unverified suggestion"
        }
    }

    public var isVerified: Bool {
        self == .verifiedInstruction || self == .manufacturerDocument
    }
}

/// How dangerous it is to work on a system without proper knowledge.
public enum HazardLevel: String, Codable, Sendable, CaseIterable, Comparable {
    case normal
    /// Pressure, hot water, moving parts.
    case caution
    /// Electrical, gas, high pressure — professional help advised.
    case dangerous

    private var rank: Int {
        switch self {
        case .normal: 0
        case .caution: 1
        case .dangerous: 2
        }
    }

    public static func < (lhs: HazardLevel, rhs: HazardLevel) -> Bool {
        lhs.rank < rhs.rank
    }
}
